+namespace {
+
+// Powers of 10 as double (exact up to 10^22)
+constexpr double POW10[] = {
+    1e0, 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8, 1e9,
+    1e10, 1e11, 1e12, 1e13, 1e14, 1e15, 1e16, 1e17, 1e18, 1e19,
+    1e20, 1e21, 1e22
+};
+
+// Powers of 10 as uint64_t (exact up to 10^19)
+constexpr uint64_t POW10_U64[] = {
+    1ULL, 10ULL, 100ULL, 1000ULL, 10000ULL, 100000ULL, 1000000ULL, 10000000ULL,
+    100000000ULL, 1000000000ULL, 10000000000ULL, 100000000000ULL,
+    1000000000000ULL, 10000000000000ULL, 100000000000000ULL,
+    1000000000000000ULL, 10000000000000000ULL, 100000000000000000ULL,
+    1000000000000000000ULL, 10000000000000000000ULL
+};
+
+// Chunk size for digit parsing (1 = scalar, 2 = pairs, 4 = quads)
+constexpr int DIGIT_CHUNK_SIZE = 4;
+
+// Fast path: try to parse as integer or simple decimal with exponent within Clinger's fast path limits
+// Returns true if successfully parsed, false if fallback needed
+bool try_fast_path(const char*& p, const char* end, double& result) {
+    const char* start = p;
+    bool negative = false;
+    
+    // Sign
+    if (p < end && *p == '-') {
+        negative = true;
+        ++p;
+    }
+    
+    // Must have at least one digit
+    if (p >= end || *p < '0' || *p > '9') return false;
+    
+    // Parse integer part with chunked digit processing
+    uint64_t mantissa = 0;
+    int digits = 0;
+    int total_digits = 0;
+    
+    // Chunked parsing for integer part
+    constexpr uint64_t CHUNK_MULT[] = {0, 10, 100, 0, 10000};
+    constexpr int CHUNK_SIZE = DIGIT_CHUNK_SIZE;
+    while (p + CHUNK_SIZE - 1 < end) {
+        bool all_digits = true;
+        uint64_t chunk_val = 0;
+        for (int i = 0; i < CHUNK_SIZE; ++i) {
+            char c = p[i];
+            if (c < '0' || c > '9') { all_digits = false; break; }
+            chunk_val = chunk_val * 10 + (c - '0');
+        }
+        if (!all_digits) break;
+        if (digits + CHUNK_SIZE <= 19) {
+            mantissa = mantissa * CHUNK_MULT[CHUNK_SIZE] + chunk_val;
+            digits += CHUNK_SIZE;
+        } else {
+            break;
+        }
+        total_digits += CHUNK_SIZE;
+        p += CHUNK_SIZE;
+    }
+    // Scalar cleanup
+    while (p < end && *p >= '0' && *p <= '9') {
+        if (digits < 19) {
+            mantissa = mantissa * 10 + (*p - '0');
+            ++digits;
+        }
+        ++total_digits;
+        ++p;
+    }
+    
+    int decimal_exponent = 0;
+    bool has_decimal = false;
+    
+    // Parse fractional part
+    if (p < end && *p == '.') {
+        has_decimal = true;
+        ++p;
+        while (p < end && *p >= '0' && *p <= '9') {
+            if (digits < 19) {
+                mantissa = mantissa * 10 + (*p - '0');
+                ++digits;
+            }
+            ++total_digits;
+            --decimal_exponent;
+            ++p;
+        }
+    }
+    
+    // Parse exponent
+    int exp_value = 0;
+    bool has_exponent = false;
+    if (p < end && (*p == 'e' || *p == 'E')) {
+        has_exponent = true;
+        ++p;
+        bool exp_negative = false;
+        if (p < end && (*p == '+' || *p == '-')) {
+            exp_negative = (*p == '-');
+            ++p;
+        }
+        if (p >= end || *p < '0' || *p > '9') return false;
+        while (p < end && *p >= '0' && *p <= '9') {
+            exp_value = exp_value * 10 + (*p - '0');
+            if (exp_value > 10000) return false;  // Too large for fast path
+            ++p;
+        }
+        if (exp_negative) exp_value = -exp_value;
+    }
+    
+    // Must end at newline or end of buffer
+    if (p >= end || *p != '\n') return false;
+    
+    // Must end at newline or end of buffer
+    if (p >= end || *p != '\n') return false;
+    
+    // Combine exponents
+    decimal_exponent += exp_value;
+    
+    // Fast path only works if we have ALL digits exactly (total_digits <= 19)
+    // and mantissa < 2^53 and |decimal_exponent| <= 22
+    constexpr uint64_t MAX_EXACT_MANTISSA = 9007199254740991ULL; // 2^53 - 1
+    
+    if (total_digits <= 19 && mantissa <= MAX_EXACT_MANTISSA && decimal_exponent >= -22 && decimal_exponent <= 22) {
+        // Exact computation possible
+        double value;
+        if (decimal_exponent >= 0) {
+            value = double(mantissa) * POW10[decimal_exponent];
+        } else {
+            value = double(mantissa) / POW10[-decimal_exponent];
+        }
+        result = negative ? -value : value;
+        ++p;  // Skip newline
+        return true;
+    }
+    
+    // Check if integer with no decimal/exponent and fits in 53 bits (all digits captured)
+    if (!has_decimal && !has_exponent && total_digits <= 19 && mantissa <= MAX_EXACT_MANTISSA) {
+        double value = double(mantissa);
+        result = negative ? -value : value;
+        ++p;  // Skip newline
+        return true;
+    }
+    
+    // Too complex for fast path, need fallback
+    p = start;  // Reset for strtod
+    return false;
+}
+
